const privacyPatterns=[
 ['DNI/NIE',/\b(?:\d{8}[A-Z]|[XYZ]\d{7}[A-Z])\b/ig],['email',/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/ig],['teléfono',/(?:\+34\s*)?(?:[6789]\d{2})(?:[ .-]?\d{3}){2}/g],['nº historia',/\b(?:nhc|n[úu]m(?:ero)?\s*de\s*historia|historia\s*cl[ií]nica)\s*[:#-]?\s*[A-Z0-9-]{4,}\b/ig],['dirección',/\b(?:calle|c\/|avenida|avda\.?|plaza|paseo|carretera)\s+[\p{L}0-9 .ºª-]{3,}/igu],['código postal',/\b\d{5}\b/g]
];
function privacyScan(text){const hits=[];privacyPatterns.forEach(([n,re])=>{re.lastIndex=0;if(re.test(text))hits.push(n)});return [...new Set(hits)]}
function escapeHtml(s){return String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function normalize(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function sentences(text){return String(text||'').replace(/\r/g,'\n').split(/\n+|(?<=[.!?;])\s+/).map(x=>x.trim()).filter(Boolean)}

