function scoreFor(sec,s){const n=normalize(s);return (cueMap[sec]||[]).reduce((a,k)=>a+(n.includes(normalize(k))?1:0),0)}
function uniqueJoin(arr){const seen=new Set(), out=[];arr.forEach(x=>{const k=normalize(x).replace(/[^a-z0-9]+/g,' ').trim();if(k&&!seen.has(k)){seen.add(k);out.push(x)}});return out.join(' ')}
function classifyInitial(text,sections){const out=Object.fromEntries(sections.map(s=>[s,[]]));sentences(text).forEach(sent=>{let best=sections.includes('Enfermedad actual / evolución longitudinal')?'Enfermedad actual / evolución longitudinal':sections[0], max=0;sections.forEach(sec=>{const sc=scoreFor(sec,sent);if(sc>max){max=sc;best=sec}});out[best].push(sent)});return Object.fromEntries(Object.entries(out).map(([k,v])=>[k,uniqueJoin(v)]))}
function extractTreatment(text){return sentences(text).filter(x=>/\b(?:mg|miligr|tratamiento|toma|pauta|escitalopram|fluoxetina|mirtazapina|lorazepam|sertralina|venlafaxina|duloxetina|vortioxetina|aripiprazol|olanzapina|risperidona|paliperidona|quetiapina|clozapina|litio|valproato|lamotrigina)\b/i.test(x)).slice(0,5).join(' ')}
function getContext(){try{return JSON.parse(localStorage.getItem('psikiaContext')||'null')}catch{return null}}
function contextText(){const c=getContext();return c?.summary||''}
function contextHeader(){const c=getContext();if(!c)return 'No consta contexto longitudinal previo guardado.';return c.summary}
function buildEvolution(text){const base=classifyInitial(text,['Evolución / enfermedad actual','Exploración psicopatológica comparativa','Juicio clínico','Plan de tratamiento','Seguimiento / próxima cita']);const out={};out['Resumen clínico longitudinal']=contextHeader();out['Evolución / enfermedad actual']=base['Evolución / enfermedad actual']||text;out['Exploración psicopatológica comparativa']=base['Exploración psicopatológica comparativa']||sentences(text).filter(x=>/consciente|orientad|discurso|crisis|agoraf|afect|futuro|duerme|come|sueño|apetito|delir|alucin|ideacion|ideación/i.test(x)).join(' ');out['Juicio clínico']=sentences(text).filter(x=>/juicio|diagnost|se mantiene|compatible/i.test(x)).join(' ')||'Se mantiene juicio clínico previo, salvo revisión facultativa.';out['Plan de tratamiento']=sentences(text).filter(x=>/mantener|retirar|iniciar|pauta|tratamiento|psicolog|enfermer|medidas|intervencion/i.test(x)).join(' ');out['Seguimiento / próxima cita']=sentences(text).filter(x=>/cita|revision|revisión|seguimiento|meses|semanas/i.test(x)).slice(-3).join(' ');return out}
function buildPTI(text){const c=contextHeader();const n=normalize(`${c} ${text}`);const goals=[];if(/depres|hipotim|anhed|apat|abul/.test(n))goals.push('Mejorar sintomatología afectiva y recuperar actividad gratificante.');if(/autocuidado|higiene|avd/.test(n))goals.push('Mejorar autonomía y regularidad en autocuidado y actividades de la vida diaria.');if(/aisla|social|cuadrilla|interaccion|interacción/.test(n))goals.push('Incrementar participación social y reducir aislamiento.');if(/ocupacional|trabaj|empleo|actividad/.test(n))goals.push('Recuperar estructura ocupacional y avanzar hacia objetivos laborales realistas.');if(/psicos|delir|alucin/.test(n))goals.push('Reducir malestar asociado a síntomas psicóticos y mejorar estrategias de afrontamiento.');if(/consumo|cannabis|alcohol|cocaina|cocaína/.test(n))goals.push('Mantener/reducir consumo y reforzar prevención de recaídas.');if(/autolit|suicid|autoagres/.test(n))goals.push('Monitorizar riesgo y consolidar plan de seguridad y estrategias de afrontamiento.');if(!goals.length)goals.push('Mejorar funcionamiento global y avanzar en los objetivos individualizados acordados durante el ingreso.');return {
 'Resumen clínico y funcional':c,
 'Necesidades / problemas activos':text||'Completar a partir de la evolución del primer mes.',
 'Objetivos del ingreso':goals.map((g,i)=>`${i+1}. ${g}`).join('\n'),
 'Intervención de Psiquiatría':'Revisión diagnóstica longitudinal, optimización y monitorización del tratamiento psicofarmacológico, coordinación del plan y reevaluación de riesgo cuando proceda.',
 'Intervención de Psicología':'Formulación compartida, intervención cognitivo-conductual/rehabilitadora adaptada a problemas activos, entrenamiento de estrategias y prevención de recaídas.',
 'Intervención de Enfermería':'Seguimiento clínico y de adherencia, educación sanitaria, apoyo en hábitos, manejo de ansiedad/estrés y objetivos de autocuidado según necesidades.',
 'Intervención de Terapia Ocupacional':'Valoración de desempeño, estructuración de rutinas, activación ocupacional, ocio significativo y progresión de objetivos comunitarios.',
 'Intervención de Trabajo Social':'Valoración sociofamiliar, prestaciones y apoyos, recursos comunitarios/tercer sector, coordinación con red y objetivos de integración.',
 'Otras intervenciones / coordinación':'Valorar intervención familiar, recursos comunitarios y coordinación con dispositivos de referencia según evolución.',
 'Indicadores de seguimiento y revisión del PTI':'Revisar consecución de objetivos, participación en programa, autonomía, funcionamiento social/ocupacional, síntomas, adherencia y riesgo.'
}}
function buildDischarge(text){const c=contextHeader();const base=classifyInitial(text,templates.discharge.sections);base['Motivo y contexto del ingreso']=base['Motivo y contexto del ingreso']||c;base['Antecedentes relevantes']=base['Antecedentes relevantes']||c;return base}
function buildEmergency(text){return classifyInitial(text,templates.emergency.sections)}
function buildReport(text,type){if(type==='evolution')return buildEvolution(text);if(type==='pti')return buildPTI(text);if(type==='discharge')return buildDischarge(text);if(type==='emergency')return buildEmergency(text);return classifyInitial(text,templates.initial.sections)}

function renderReport(){const box=$('#reportSections');box.innerHTML='';currentSections.forEach(sec=>{const d=document.createElement('div');d.className='sectionbox';d.innerHTML=`<div class="sectiontitle">${escapeHtml(sec)}</div><div class="sectiontext" contenteditable="true" data-sec="${escapeHtml(sec)}">${escapeHtml(currentReport[sec]||'')}</div>`;box.appendChild(d)});$$('[data-sec]').forEach(el=>el.addEventListener('input',()=>{currentReport[el.dataset.sec]=el.innerText.trim()}))}
function reportText(){return currentSections.map(s=>`${s.toUpperCase()}\n${currentReport[s]||'—'}`).join('\n\n')}
function showTab(name){$$('section.tab').forEach(x=>x.classList.remove('active'));$$('nav button').forEach(x=>x.classList.remove('active'));$('#tab-'+name).classList.add('active');$(`nav button[data-tab="${name}"]`).classList.add('active')}
$$('nav button').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.tab)));

function updatePrivacy(){const text=$('#raw').value,h=privacyScan(text),el=$('#privacyResult');if(!text.trim()){el.innerHTML='';return}el.innerHTML=h.length?`<div class="notice danger">⚠️ Posibles identificadores: <b>${escapeHtml(h.join(', '))}</b>. Revisa el dictado.</div>`:'<div class="notice ok">✓ No se detectan identificadores directos obvios. Esto no garantiza anonimización completa.</div>'}
$('#raw').addEventListener('input',updatePrivacy);

