function renderClinicalControl(text){const n=normalize(`${text} ${reportText()}`);const ds=diagnosisMap.filter(d=>d.terms.some(t=>n.includes(normalize(t))));$('#diagnosisSuggestions').innerHTML=ds.length?ds.map(d=>`<div class="suggestion"><strong>${d.code}</strong> — ${escapeHtml(d.label)}<div class="small">Sugerencia editable. Validar en eCIEMaps y según criterios clínicos.</div></div>`).join(''):'<p class="small">No hay una sugerencia CIE conservadora a partir del texto.</p>';
 const found=[];meds.forEach(([g,a])=>{const hit=a.find(x=>n.includes(normalize(x)));if(hit)found.push([g,hit])});$('#medSuggestions').innerHTML=found.length?found.map(x=>`<div class="suggestion"><strong>${escapeHtml(x[0])}</strong><span class="badge">${escapeHtml(x[1])}</span></div>`).join(''):'<p class="small">No se han detectado psicofármacos del diccionario local.</p>';
 const miss=[];if(!/autolit|suicid|autoagres|riesgo/.test(n))miss.push('No consta de forma explícita una valoración de riesgo autolítico/autoagresivo.');if($('#tipo').value==='initial'&&!/durante|desde hace|semanas|meses|dias|días/.test(n))miss.push('La cronología/duración del síndrome no está claramente expresada.');if(/depres/.test(n)&&!/semanas|dias|días|meses/.test(n))miss.push('En clínica depresiva conviene explicitar duración del síndrome para contrastar criterios temporales.');if(/panico|pánico/.test(n)&&!/inesperad|evitacion|evitación|preocupacion|preocupación/.test(n))miss.push('En pánico, revisar si las crisis son inesperadas y la preocupación/cambio conductual posterior.');$('#missingSuggestions').innerHTML=miss.length?miss.map(x=>`<div class="suggestion">${escapeHtml(x)}</div>`).join(''):'<div class="notice ok">Sin vacíos básicos detectados por las reglas actuales.</div>'}

