function sourceHtml(ids){if(!ids.length)return '<div class="source">Fuente: formulación clínica / psicoeducación general.</div>';return `<div class="source">Fuentes: ${ids.map(id=>{const s=therapySources[id];return `<a href="${s.url}" target="_blank" rel="noopener noreferrer">${escapeHtml(s.name)}</a>`}).join(' · ')}</div>`}
function therapyCard(m){return `<div class="therapy-card" data-module="${m.id}"><h4>${escapeHtml(m.title)} <span class="badge ${m.badge}">${escapeHtml(m.level)}</span></h4><div class="why">${escapeHtml(m.why)}</div><ol class="steps">${m.steps.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ol><div class="small"><b>${escapeHtml(m.homework)}</b></div>${sourceHtml(m.sources)}<div class="therapy-actions"><button class="secondary" data-copy="${m.id}">Copiar propuesta</button><button class="secondary" data-plan="${m.id}">Añadir frase al plan</button></div></div>`}
function matchModules(text){const n=normalize(text);const scored=therapyModules.map(m=>({m,score:m.tags.reduce((a,t)=>a+(n.includes(normalize(t))?2:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);const out=[];for(const x of scored){if(!out.some(y=>y.id===x.m.id))out.push(x.m);if(out.length>=6)break}return out}
function renderTherapy(text){const mods=matchModules(`${contextText()} ${text} ${reportText()}`);$('#therapySummary').textContent=mods.length?`Se han seleccionado ${mods.length} propuestas según los problemas descritos. Prioriza 1–2 por sesión.`:'No se han detectado dianas claras. Puedes buscar manualmente en la biblioteca de técnicas.';$('#therapyCards').innerHTML=mods.map(therapyCard).join('');bindTherapyButtons()}
function bindTherapyButtons(){$$('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{const m=therapyModules.find(x=>x.id===b.dataset.copy);const txt=`${m.title}\n\n${m.steps.map((x,i)=>`${i+1}. ${x}`).join('\n')}\n\n${m.homework}\n\n${m.plan}`;try{await navigator.clipboard.writeText(txt);alert('Propuesta copiada.')}catch{alert(txt)}}));$$('[data-plan]').forEach(b=>b.addEventListener('click',()=>{const m=therapyModules.find(x=>x.id===b.dataset.plan);const sec=currentSections.find(x=>/Plan de tratamiento|Intervención de Psicología|Plan de tratamiento e intervención/i.test(x));if(!sec)return alert('No hay un apartado de plan compatible en el informe actual.');currentReport[sec]=`${currentReport[sec]||''}${currentReport[sec]?'\n':''}${m.plan}`;renderReport();alert('Añadido como borrador al plan. Revísalo antes de usarlo.')}))}
function renderTherapyLibrary(query=''){const n=normalize(query);const mods=n?therapyModules.filter(m=>normalize(`${m.title} ${m.tags.join(' ')} ${m.why}`).includes(n)||m.tags.some(t=>normalize(t).includes(n))):therapyModules;$('#therapyLibrary').innerHTML=mods.slice(0,12).map(therapyCard).join('');bindTherapyButtons()}
$('#therapyFilter').addEventListener('input',e=>renderTherapyLibrary(e.target.value));renderTherapyLibrary();


